(function () {

  function initPaperLinks() {


    // ----------------------------------------------------
    // Style
    // ----------------------------------------------------

    const style = document.createElement('style');

    style.textContent =
      '.paper-link {' +
      'color:#376d91;' +
      'font-weight:800;' +
      'text-decoration:underline;' +
      'cursor:pointer;' +
      '}' +
      '.paper-link:hover {' +
      'color:#17324a;' +
      '}';

    document.head.appendChild(style);


    // ----------------------------------------------------
    // Link creator
    // ----------------------------------------------------

    function createPaperLink(paperId) {

      const url = PAPER_LINKS[paperId];

      if (!url) {
        return null;
      }

      const link = document.createElement('a');

      link.href = url;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      link.textContent = paperId;
      link.className = 'paper-link';

      return link;
    }


    // ----------------------------------------------------
    // 收集網站所有 Paper ID
    // ----------------------------------------------------

    const websitePaperIds = new Set();

    document
      .querySelectorAll('.paper-ids b, .paper-time-table td')
      .forEach(element => {

        const paperId =
          element.textContent.trim();

        if (/^[0-9]{4}$/.test(paperId)) {
          websitePaperIds.add(paperId);
        }

      });


    // ----------------------------------------------------
    // Session 卡片 Paper ID
    // ----------------------------------------------------

    document
      .querySelectorAll('.paper-ids b')
      .forEach(element => {

        const paperId =
          element.textContent.trim();

        const link =
          createPaperLink(paperId);

        if (link) {
          element.replaceWith(link);
        }

      });


    // ----------------------------------------------------
    // Paper ID Schedule
    // ----------------------------------------------------

    document
      .querySelectorAll('.paper-time-table td')
      .forEach(element => {

        const paperId =
          element.textContent.trim();

        if (!/^[0-9]{4}$/.test(paperId)) {
          return;
        }

        const link =
          createPaperLink(paperId);

        if (!link) {
          return;
        }

        element.textContent = '';
        element.appendChild(link);

      });


    // ----------------------------------------------------
    // 完整性檢查
    // ----------------------------------------------------

    const missingLinks =
      [...websitePaperIds]
        .filter(id => !PAPER_LINKS[id])
        .sort((a, b) => Number(a) - Number(b));


    const extraLinks =
      Object.keys(PAPER_LINKS)
        .filter(id => !websitePaperIds.has(id))
        .sort((a, b) => Number(a) - Number(b));


    console.log(
      '[CACS2026] Paper IDs on website:',
      websitePaperIds.size
    );


    console.log(
      '[CACS2026] Google Drive PDF links:',
      Object.keys(PAPER_LINKS).length
    );


    if (missingLinks.length === 0) {

      console.log(
        '[CACS2026] All website Paper IDs have PDF links.'
      );

    } else {

      console.warn(
        '[CACS2026] Website Paper IDs WITHOUT PDF:',
        missingLinks
      );

    }


    if (extraLinks.length > 0) {

      console.warn(
        '[CACS2026] Drive PDFs NOT found on website:',
        extraLinks
      );

    }

  }


  if (document.readyState === 'loading') {

    document.addEventListener(
      'DOMContentLoaded',
      initPaperLinks
    );

  } else {

    initPaperLinks();

  }

})();
